```js
// --- Brick collision (swept AABB) ----------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// ... (unchanged collides)

// Continuous (swept) test between the previous and the current ball position.
// Treats the ball as a point moving along the segment and the brick as its
// Minkowski expansion (brick + ball radius), then applies the slab method:
// the first contact time and the face(s) touched. Returns null when the
// segment never crosses the expanded box.
//
// A discrete sample before and after the move misses a brick crossed entirely
// within one step (the ball at ballSpeed(6) × dt_max moves 35.5 px against a
// 34 px brick + diameter).
function sweptContact(prevX, prevY, ball, brick) {
  const bx = brick.x - ball.r;
  const by = brick.y - ball.r;
  const bw = brick.w + 2 * ball.r;
  const bh = brick.h + 2 * ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Entry/exit times per axis (slab method); null when the axis has no motion.
  let xEntry = null;
  let xExit = Infinity;
  let xFace = null;
  let yEntry = null;
  let yExit = Infinity;
  let yFace = null;

  if (dx === 0) {
    if (prevX <= bx || prevX >= bx + bw) return null; // parallel and outside
  } else {
    const t1 = (bx - prevX) / dx;
    const t2 = (bx + bw - prevX) / dx;
    xEntry = Math.min(t1, t2);
    xExit = Math.max(t1, t2);
    xFace = dx > 0 ? 'left' : 'right';
  }
  if (dy === 0) {
    if (prevY <= by || prevY >= by + bh) return null;
  } else {
    const t1 = (by - prevY) / dy;
    const t2 = (by + bh - prevY) / dy;
    yEntry = Math.min(t1, t2);
    yExit = Math.max(t1, t2);
    yFace = dy > 0 ? 'top' : 'bottom';
  }

  if (xEntry === null && yEntry === null) return null; // no motion at all
  const tEntry = Math.max(xEntry ?? -Infinity, yEntry ?? -Infinity);
  const tExit = Math.min(xExit, yExit);
  if (tEntry > tExit || tEntry > 1 || tExit < 0) return null;

  const faces = [];
  if (xEntry !== null && xEntry === tEntry) faces.push(xFace);
  if (yEntry !== null && yEntry === tEntry) faces.push(yFace);
  return { t: tEntry, faces };
}
```

