// them. One bounce per axis, whatever the number of bricks touched: two flips
// on a grid seam (BRICK_GAP 8 px < ball diameter 14 px) would cancel out and
// let the ball through.
function bounceOffBricks(prevX, prevY, ball, hits) {
  const prevBall = { x: prevX, y: prevY, r: ball.r };
  const overlapping = hits.filter((brick) => collides(prevBall, brick));

  if (overlapping.length > 0) {
    // The ball was already inside at least one brick: the touched face is the
    // one with the smallest penetration. Equal penetrations on both axes mean
    // a corner (both components flip).
    ... (unchanged penetration code)
    return;
  }

  // The ball crossed the brick(s) within this step without overlapping at the
  // previous position: resolve at the first contact.
  let best = null;
  for (const brick of hits) {
    const contact = sweptContact(prevX, prevY, ball, brick);
    if (contact && (best === null || contact.t < best.contact.t)) {
      best = { contact, brick };
    }
  }
  if (best === null) return;

  const { contact, brick } = best;
  const onX = contact.faces.includes('left') || contact.faces.includes('right');
  const onY = contact.faces.includes('top') || contact.faces.includes('bottom');
  if (onX) {
    ball.vx = -ball.vx;
    ball.x = contact.faces.includes('left') ? brick.x - ball.r : brick.x + brick.w + ball.r;
  }
  if (onY) {
    ball.vy = -ball.vy;
    ball.y = contact.faces.includes('bottom') ? brick.y + brick.h + ball.r : brick.y - ball.r;
  }
}
