// 34 px brick + diameter); the slab method resolves at the first contact, so
// the bounce does not depend on the step size.
function sweptContact(prevX, prevY, ball, brick) {
  const bx = brick.x - ball.r;
  const by = brick.y - ball.r;
  const bw = brick.w + 2 * ball.r;
  const bh = brick.h + 2 * ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Entry/exit times per axis; null when the axis has no motion.
  let xEntry = null;
  let xExit = Infinity;
  let xFace = null;
  let yEntry = null;
  let yExit = Infinity;
  let yFace = null;

  if (dx === 0) {
    if (prevX <= bx || prevX >= bx + bw) return null; // parallel and outside
  } else {
    const t1 = (bx - prevX) / dx;
    const t2 = (bx + bw - prevX) / dx;
    xEntry = Math.min(t1, t2);
    xExit = Math.max(t1, t2);
    xFace = dx > 0 ? 'left' : 'right';
  }
  if (dy === 0) {
    if (prevY <= by || prevY >= by + bh) return null; // parallel and outside
  } else {
    const t1 = (by - prevY) / dy;
    const t2 = (by + bh - prevY) / dy;
    yEntry = Math.min(t1, t2);
    yExit = Math.max(t1, t2);
    yFace = dy > 0 ? 'top' : 'bottom';
  }

  if (xEntry === null && yEntry === null) return null; // no motion at all
  const tEntry = Math.max(xEntry ?? -Infinity, yEntry ?? -Infinity);
  const tExit = Math.min(xExit, yExit);
  if (tEntry > tExit || tEntry > 1 || tExit < 0) return null;

  const faces = [];
  if (xEntry !== null && xEntry === tEntry) faces.push(xFace);
  if (yEntry !== null && yEntry === tEntry) faces.push(yFace);
  return { t: tEntry, faces };
}

// Reflects the ball off the bricks it hit in this pass and pushes it out of
// them. One bounce per axis, whatever the number of bricks touched: two flips
// on a grid seam (BRICK_GAP 8 px < ball diameter 14 px) would cancel out and
// let the ball through.
function bounceOffBricks(prevX, prevY, ball, hits) {
  const prevBall = { x: prevX, y: prevY, r: ball.r };
  const overlapping = hits.filter((brick) => collides(prevBall, brick));

  if (overlapping.length > 0) {
    // The ball was already inside at least one brick: the touched face is the
    // one with the smallest penetration. Equal penetrations on both axes mean
    // a corner (both components flip).
    let min = Infinity;
    let faces = new Set();
    for (const brick of overlapping) {
      const pens = {
        left: ball.x + ball.r - brick.x,
        right: brick.x + brick.w - (ball.x - ball.r),
        top: ball.y + ball.r - brick.y,
        bottom: brick.y + brick.h - (ball.y - ball.r),
      };
      const m = Math.min(pens.left, pens.right, pens.top, pens.bottom);
      if (m < min) {
        min = m;
        faces = new Set(
          Object.entries(pens).filter(([, v]) => v === m).map(([k]) => k),
        );
      } else if (m === min) {
        Object.entries(pens)
          .filter(([, v]) => v === m)
          .forEach(([k]) => faces.add(k));
      }
    }

    if (faces.has('left') || faces.has('right')) {
      ball.vx = -ball.vx;
      ball.x = faces.has('left')
        ? Math.min(...overlapping.map((b) => b.x)) - ball.r
        : Math.max(...overlapping.map((b) => b.x + b.w)) + ball.r;
    }
    if (faces.has('top') || faces.has('bottom')) {
      ball.vy = -ball.vy;
      ball.y = faces.has('top')
        ? Math.min(...overlapping.map((b) => b.y)) - ball.r
        : Math.max(...overlapping.map((b) => b.y + b.h)) + ball.r;
    }
    return;
  }

  // The ball crossed the brick(s) within this step without overlapping at the
  // previous position: resolve at the first contact.
  let best = null;
  for (const brick of hits) {
    const contact = sweptContact(prevX, prevY, ball, brick);
    if (contact && (best === null || contact.t < best.contact.t)) {
      best = { contact, brick };
    }
  }
  if (best === null) return;

  const { contact, brick } = best;
  const onX = contact.faces.includes('left') || contact.faces.includes('right');
  const onY = contact.faces.includes('top') || contact.faces.includes('bottom');
  if (onX) {
    ball.vx = -ball.vx;
    ball.x = contact.faces.includes('left')
      ? brick.x - ball.r
      : brick.x + brick.w + ball.r;
  }
  if (onY) {
    ball.vy = -ball.vy;
    ball.y = contact.faces.includes('bottom')
      ? brick.y + brick.h + ball.r
      : brick.y - ball.r;
  }
}

