// Bricks — swept AABB, resolved once per pass: a seam between two bricks
// must not double-invert the ball.
const hits = [];
for (const brick of state.bricks) {
  if (!brick.alive) continue;
  if (!sweptContact(prevX, prevY, ball, brick)) continue;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
  hits.push(brick);
}
if (hits.length > 0) {
  bounceOffBricks(prevX, prevY, ball, hits);
}

